25.   constructor(private readonly percent: number) {
26.     if (!Number.isFinite(percent) || percent < 0 || percent > 100) {
27.       throw new RangeError(`percent must be between 0 and 100 (got ${percent})`);
28.     }
29.   }
30. 
31.   computeDiscountCents(subtotalCents: number): number {
32.     if (subtotalCents <= 0) return 0;
33.     return Math.floor((subtotalCents * this.percent) / 100);
34.   }
35. }
36. 
37. /** Flat amount off the subtotal. */
38. export class FixedAmountDiscountPolicy implements DiscountPolicy {
39.   constructor(private readonly amountCents: number) {
40.     if (!Number.isInteger(amountCents) || amountCents < 0) {
41.       throw new RangeError(
42.         `amountCents must be a non-negative integer (got ${amountCents})`,
43.       );
44.     }
45.   }
46. 
47.   computeDiscountCents(subtotalCents: number): number {
48.     if (subtotalCents <= 0) return 0;
49.     return Math.min(this.amountCents, subtotalCents);
50.   }
51. }
