  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax computation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(product("a", 10000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // tax = floor(10000 * 0.0875) = 875
      expect(result.totals.taxCents).toBe(875);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "US",
      });
      cart.add(product("a", 10000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=10000, discount=2000, taxable=8000, tax=800
      expect(result.totals.discountCents).toBe(2000);
      expect(result.totals.taxCents).toBe(800);
    });

    it("propagates async tax provider rejection", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "rate service down",
      );
    });

    it("throws RangeError when async tax provider returns invalid rate", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(RangeError);
    });
  });

  describe("full pipeline composition", () => {
    it("combines priceFetcher + inventoryChecker + asyncTaxProvider + discount + shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US",
      });
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 2000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation((id: string) =>
          id === "a" ? Promise.resolve(1200) : Promise.resolve(2500),
        ),
      };

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Refreshed: a=1200*2=2400, b=2500*1=2500 → subtotal=4900
      expect(result.totals.subtotalCents).toBe(4900);
      // discount = floor(4900 * 10%) = 490
      expect(result.totals.discountCents).toBe(490);
      // taxable = 4900 - 490 = 4410, tax = floor(4410 * 0.08) = 352
      expect(result.totals.taxCents).toBe(352);
      // shipping = 500 (flat)
      expect(result.totals.shippingCents).toBe(500);
      // total = 4410 + 352 + 500 = 5262
      expect(result.totals.totalCents).toBe(5262);
    });

    it("checkout without collaborators uses sync pipeline", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
    });

    it("returns the refreshed lines in the result", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(result.lines[0]!.product.unitPriceCents).toBe(2000);
      expect(result.lines[0]!.quantity).toBe(2);
    });
  });
});

