const line = (id: string, weightGrams: number, quantity = 1): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any lines", () => {
    expect(calc.computeShippingCents([line("a", 500)], 10000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts 0 for flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts 0 for freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flatCents for non-empty cart below threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line("a", 100)], 4999)).toBe(599);
    });

    it("returns 0 when subtotal meets free threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line("a", 100)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line("a", 100)], 6000)).toBe(0);
    });

    it("returns 0 for empty cart regardless of subtotal", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([], 10000)).toBe(0);
    });

    it("returns flatCents without threshold configured", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([line("a", 100)], 99999)).toBe(799);
    });

    it("freeOverCents of 0 makes everything free when lines exist", () => {
      const calc = new FlatShippingCalculator(500, 0);
      expect(calc.computeShippingCents([line("a", 100)], 0)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      1500,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const noWeightLine: CartLine = {
        product: { id: "x", name: "X", unitPriceCents: 100 },
        quantity: 3,
      };
      expect(calc.computeShippingCents([noWeightLine], 5000)).toBe(0);
    });

    it("selects first bracket (weight at boundary)", () => {
      expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(300);
    });

    it("selects first bracket (weight below boundary)", () => {
      expect(calc.computeShippingCents([line("a", 300)], 5000)).toBe(300);
    });

    it("selects second bracket when weight exceeds first boundary", () => {
      expect(calc.computeShippingCents([line("a", 501)], 5000)).toBe(700);
    });

    it("selects second bracket at its boundary", () => {
      expect(calc.computeShippingCents([line("a", 2000)], 5000)).toBe(700);
    });

    it("selects third bracket", () => {
      expect(calc.computeShippingCents([line("a", 3000)], 5000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(calc.computeShippingCents([line("a", 6000)], 5000)).toBe(1500);
    });

    it("uses heaviest bracket cost when no overflow specified", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      expect(calcNoOverflow.computeShippingCents([line("a", 5000)], 5000)).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const calcUnsorted = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      expect(calcUnsorted.computeShippingCents([line("a", 400)], 5000)).toBe(300);
    });

    it("accumulates weight across multiple lines", () => {
      // 2 items of 300g = 600g → second bracket
      expect(calc.computeShippingCents([line("a", 300, 2)], 5000)).toBe(700);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product, CartLine } from "../src/product.ts";

const product = (id: string, unitPriceCents: number, weightGrams = 0): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  weightGrams,
});

describe("Cart - line management", () => {
  it("add() creates a new line", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add() merges quantity when product already exists", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add() rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
  });

  it("add() rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
  });

  it("add() rejects negative unit price", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("remove() deletes a known product and returns true", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove() returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity() changes quantity of existing product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity(0) removes the product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity() throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 5)).toThrow("Product x is not in the cart");
  });

  it("updateQuantity() rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity() rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear() empties the cart", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot() returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.quantity).toBe(2);
    // Mutating snapshot doesn't affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart - pricing pipeline", () => {
  it("empty cart totals are all zero", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("subtotal = sum of (unitPrice * qty)", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 3);
    expect(cart.totals().subtotalCents).toBe(3500);
  });

  it("discount is clamped to [0, subtotal]", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
  });

  it("negative discount is clamped to 0", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: mockDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("tax is computed on discounted subtotal", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn((taxable: number, _region: string) =>
        Math.floor(taxable * 0.1),
      ),
    };
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
    });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    // subtotal=1000, discount=200, taxable=800, tax=80
    expect(t.taxCents).toBe(80);
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US");
  });

  it("shipping receives discounted subtotal", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn(
        (_lines: readonly CartLine[], subtotalCents: number) =>
          subtotalCents >= 5000 ? 0 : 500,
      ),
    };
    const cart = new Cart({ shippingCalculator: mockShipping });
    cart.add(product("a", 3000), 1);
    const t = cart.totals();
    expect(t.shippingCents).toBe(500);
    expect(mockShipping.computeShippingCents).toHaveBeenCalled();
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(90),
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      shippingCalculator: mockShipping,
    });
    cart.add(product("a", 1000), 1);
    const t = cart.totals();
    // subtotal=1000, discount=100, discountedSubtotal=900, tax=90, shipping=500
    expect(t.totalCents).toBe(900 + 90 + 500);
  });

  it("uses default region 'US' when not specified", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(product("a", 100), 1);
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(100, "US");
  });

  it("uses custom region when specified", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: mockTax, region: "FR" });
    cart.add(product("a", 100), 1);
    cart.totals();
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(100, "FR");
  });

  it("negative tax result is clamped to 0", () => {
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: mockTax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("negative shipping result is clamped to 0", () => {
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: mockShipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const product = (id: string, unitPriceCents: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
});

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      // New price: 1500 * 2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("throws when fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws when fetcher returns non-integer price", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates fetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("network error")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("network error");
    });
  });

  describe("inventory check", () => {
    it("passes when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          reason: "out of stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(2);
        expect(err.available).toBe(0);
        expect(err.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial (availableQuantity < requested)", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(3);
      }
    });

    it("first denial wins when multiple products fail", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 1);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockImplementation((id: string) => {
          if (id === "a") return Promise.resolve({ available: false, reason: "no stock A" });
          return Promise.resolve({ available: false, reason: "no stock B" });
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        // First product checked should be the one that throws
        const err = e as InventoryError;
        expect(err.message).toContain("no stock");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax computation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(product("a", 10000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // tax = floor(10000 * 0.0875) = 875
      expect(result.totals.taxCents).toBe(875);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "US",
      });
      cart.add(product("a", 10000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=10000, discount=2000, taxable=8000, tax=800
      expect(result.totals.discountCents).toBe(2000);
      expect(result.totals.taxCents).toBe(800);
    });

    it("propagates async tax provider rejection", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "rate service down",
      );
    });

    it("throws RangeError when async tax provider returns invalid rate", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(2.0),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(RangeError);
    });
  });

  describe("full pipeline composition", () => {
    it("combines priceFetcher + inventoryChecker + asyncTaxProvider + discount + shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US",
      });
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 2000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation((id: string) =>
          id === "a" ? Promise.resolve(1200) : Promise.resolve(2500),
        ),
      };

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Refreshed: a=1200*2=2400, b=2500*1=2500 → subtotal=4900
      expect(result.totals.subtotalCents).toBe(4900);
      // discount = floor(4900 * 10%) = 490
      expect(result.totals.discountCents).toBe(490);
      // taxable = 4900 - 490 = 4410, tax = floor(4410 * 0.08) = 352
      expect(result.totals.taxCents).toBe(352);
      // shipping = 500 (flat)
      expect(result.totals.shippingCents).toBe(500);
      // total = 4410 + 352 + 500 = 5262
      expect(result.totals.totalCents).toBe(5262);
    });

    it("checkout without collaborators uses sync pipeline", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
    });

    it("returns the refreshed lines in the result", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(result.lines[0]!.product.unitPriceCents).toBe(2000);
      expect(result.lines[0]!.quantity).toBe(2);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { refreshPrices, InventoryError, type PriceFetcher } from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("refreshPrices", () => {
  const lines: CartLine[] = [
    { product: { id: "a", name: "A", unitPriceCents: 1000 }, quantity: 2 },
    { product: { id: "b", name: "B", unitPriceCents: 2000 }, quantity: 1 },
  ];

  it("updates prices from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation((id: string) =>
        id === "a" ? Promise.resolve(1500) : Promise.resolve(2500),
      ),
    };

    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.unitPriceCents).toBe(1500);
    expect(result[1]!.product.unitPriceCents).toBe(2500);
  });

  it("preserves quantity and other product fields", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };

    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.quantity).toBe(2);
    expect(result[0]!.product.name).toBe("A");
    expect(result[0]!.product.id).toBe("a");
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

