import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 for any positive taxable amount", () => {
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
  });

  it("returns 0 for zero taxable amount", () => {
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for any region", () => {
    expect(calc.computeTaxCents(5000, "FR")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects default rate < 0", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects default rate > 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects non-finite default rate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects a rate < 0 in the rates map", () => {
      expect(() => new RegionalTaxCalculator({ US: -0.1 })).toThrow(RangeError);
    });

    it("rejects a rate > 1 in the rates map", () => {
      expect(() => new RegionalTaxCalculator({ US: 1.5 })).toThrow(RangeError);
    });

    it("rejects NaN rate in the rates map", () => {
      expect(() => new RegionalTaxCalculator({ US: NaN })).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(() => new RegionalTaxCalculator({ US: 0, FR: 1 }, 0.5)).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it("uses region-specific rate when available", () => {
      // 8.75% of 10000 = 875.0 → 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 10000 = 500
      expect(calc.computeTaxCents(10000, "AU")).toBe(500);
    });

    it("rounds down to nearest cent", () => {
      // 20% of 1001 = 200.2 → 200
      expect(calc.computeTaxCents(1001, "FR")).toBe(200);
    });

    it("returns 0 for zero taxable", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(calc.computeTaxCents(-1000, "US-CA")).toBe(0);
    });

    it("handles large taxable amounts", () => {
      // 20% of 1,000,000 = 200,000
      expect(calc.computeTaxCents(1_000_000, "FR")).toBe(200_000);
    });

    it("default rate of 0 yields 0 for unknown regions", () => {
      const calc2 = new RegionalTaxCalculator({ US: 0.1 });
      expect(calc2.computeTaxCents(5000, "XX")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 for zero taxable", async () => {
    const provider: AsyncTaxRateProvider = { getRate: vi.fn().mockResolvedValue(0.1) };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = { getRate: vi.fn().mockResolvedValue(0.1) };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("computes tax using fetched rate and floors result", async () => {
    const provider: AsyncTaxRateProvider = { getRate: vi.fn().mockResolvedValue(0.0875) };
    const calc = new AsyncTaxCalculator(provider);
    // 8.75% of 1001 = 87.5875 → 87
    expect(await calc.computeTaxCents(1001, "US-CA")).toBe(87);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("throws RangeError for rate > 1", async () => {
    const provider: AsyncTaxRateProvider = { getRate: vi.fn().mockResolvedValue(1.5) };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for rate < 0", async () => {
    const provider: AsyncTaxRateProvider = { getRate: vi.fn().mockResolvedValue(-0.1) };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate", async () => {
    const provider: AsyncTaxRateProvider = { getRate: vi.fn().mockResolvedValue(NaN) };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow("network");
  });
});

describe("totalLineWeightGrams", () => {
